-- SELECT-only acceptance checks. Every violations value must be zero.
-- Run in the portal database after database/user_administration.sql.
SELECT 'duplicate_usernames' AS check_name, COUNT(*) AS violations FROM (SELECT LOWER(TRIM(username)) FROM users GROUP BY LOWER(TRIM(username)) HAVING COUNT(*)>1) d;
SELECT 'duplicate_normalized_emails' AS check_name, COUNT(*) AS violations FROM (SELECT LOWER(TRIM(email)) FROM users WHERE email IS NOT NULL GROUP BY LOWER(TRIM(email)) HAVING COUNT(*)>1) d;
SELECT 'cross_identity_collisions' AS check_name, COUNT(*) AS violations FROM users a JOIN users b ON LOWER(TRIM(a.username))=LOWER(TRIM(b.email)) AND a.id<>b.id;
SELECT 'users_without_security_group' AS check_name, COUNT(*) AS violations FROM users u WHERE NOT EXISTS (SELECT 1 FROM user_roles ur WHERE ur.user_id=u.id);
SELECT 'invalid_role_mappings' AS check_name, COUNT(*) AS violations FROM user_roles ur LEFT JOIN roles r ON r.id=ur.role_id LEFT JOIN users u ON u.id=ur.user_id WHERE r.id IS NULL OR u.id IS NULL;
-- Existing roles have no inactive/deleted flag; assignability is managed metadata.
SELECT 'unassignable_groups_assigned' AS check_name, COUNT(*) AS violations FROM user_roles ur LEFT JOIN role_administration_profiles p ON p.role_id=ur.role_id WHERE p.role_id IS NULL OR p.assignable<>1;
SELECT 'district_required_scope_missing' AS check_name, COUNT(*) AS violations FROM users u WHERE EXISTS (SELECT 1 FROM admin_user_roles r WHERE r.user_id=u.id AND r.scope_type='DISTRICT') AND NOT EXISTS(SELECT 1 FROM admin_user_roles r WHERE r.user_id=u.id AND r.scope_type IN ('GLOBAL','NATIONAL')) AND NOT EXISTS(SELECT 1 FROM user_district_scopes s JOIN districts d ON d.id=s.district_id AND d.status='active' WHERE s.user_id=u.id AND s.status='active');
SELECT 'school_required_scope_missing' AS check_name, COUNT(*) AS violations FROM users u WHERE EXISTS (SELECT 1 FROM admin_user_roles r WHERE r.user_id=u.id AND r.scope_type='SCHOOL') AND NOT EXISTS(SELECT 1 FROM admin_user_roles r WHERE r.user_id=u.id AND r.scope_type IN ('GLOBAL','NATIONAL')) AND NOT EXISTS(SELECT 1 FROM user_school_scopes s JOIN schools sch ON sch.id=s.school_id AND sch.status='active' JOIN districts d ON d.id=sch.district_id AND d.status='active' WHERE s.user_id=u.id AND s.status='active');
SELECT 'national_required_scope_missing' AS check_name, COUNT(*) AS violations FROM users u WHERE EXISTS(SELECT 1 FROM admin_user_roles r WHERE r.user_id=u.id AND r.scope_type='NATIONAL') AND NOT EXISTS(SELECT 1 FROM admin_user_roles r WHERE r.user_id=u.id AND r.scope_type='GLOBAL') AND NOT EXISTS(SELECT 1 FROM user_national_scopes s WHERE s.user_id=u.id AND s.status='active');
SELECT 'repair_required_scope_missing' AS check_name, COUNT(*) AS violations FROM users u WHERE EXISTS(SELECT 1 FROM admin_user_roles r WHERE r.user_id=u.id AND r.scope_type='REPAIR_LOCATION') AND NOT EXISTS(SELECT 1 FROM admin_user_roles r WHERE r.user_id=u.id AND r.scope_type='GLOBAL') AND NOT EXISTS(SELECT 1 FROM user_service_location_scopes s JOIN service_locations l ON l.id=s.service_location_id AND l.is_active=1 AND l.location_type='REPAIR_CENTRE' WHERE s.user_id=u.id AND s.status='active');
-- School district is derived from schools, never duplicated on user_school_scopes.
-- Selected district filters are checked by the mutation API before insertion.
SELECT 'school_scope_district_mismatch' AS check_name, COUNT(*) AS violations FROM user_school_scopes s LEFT JOIN schools sch ON sch.id=s.school_id LEFT JOIN districts d ON d.id=sch.district_id WHERE s.status='active' AND (sch.id IS NULL OR d.id IS NULL);
SELECT 'incompatible_stale_scopes' AS check_name, COUNT(*) AS violations FROM admin_user_scopes s WHERE EXISTS(SELECT 1 FROM admin_user_roles r WHERE r.user_id=s.user_id AND r.scope_type='GLOBAL') OR (s.scope_type IN ('SCHOOL','DISTRICT') AND EXISTS(SELECT 1 FROM admin_user_roles r WHERE r.user_id=s.user_id AND r.scope_type='NATIONAL')) OR NOT EXISTS(SELECT 1 FROM admin_user_roles r WHERE r.user_id=s.user_id AND r.scope_type=s.scope_type);
SELECT 'active_users_invalid_scope_entities' AS check_name, COUNT(*) AS violations FROM admin_user_scopes s JOIN users u ON u.id=s.user_id WHERE u.status='active' AND s.entity_active<>1;
SELECT 'missing_scope_entities' AS check_name,
 (SELECT COUNT(*) FROM user_district_scopes s LEFT JOIN districts d ON d.id=s.district_id WHERE s.status='active' AND d.id IS NULL) +
 (SELECT COUNT(*) FROM user_school_scopes s LEFT JOIN schools d ON d.id=s.school_id WHERE s.status='active' AND d.id IS NULL) +
 (SELECT COUNT(*) FROM user_service_location_scopes s LEFT JOIN service_locations d ON d.id=s.service_location_id WHERE s.status='active' AND d.id IS NULL) AS violations;
SELECT 'last_active_super_admin' AS check_name, IF(COUNT(DISTINCT u.id)>0,0,1) AS violations FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.status='active' AND r.name='SUPER_ADMIN';
SELECT 'raw_setup_reset_credentials' AS check_name, COUNT(*) AS violations FROM password_reset_requests WHERE token_hash NOT LIKE '$argon2id$%' OR LENGTH(request_id)<>52 OR purpose NOT IN ('ACCOUNT_SETUP','PASSWORD_RESET');
SELECT 'unexpected_plain_token_columns' AS check_name, COUNT(*) AS violations FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='password_reset_requests' AND column_name IN ('token','secret','raw_token','setup_token');
SELECT 'plaintext_passwords' AS check_name, COUNT(*) AS violations FROM users WHERE password_hash NOT LIKE '$argon2id$%';
SELECT 'missing_auth_version' AS check_name, COUNT(*) AS violations FROM users WHERE auth_version IS NULL OR auth_version<1;
SELECT 'secrets_in_security_audit' AS check_name, COUNT(*) AS violations FROM audit_logs WHERE (module IN ('security','user_administration') OR action LIKE '%PASSWORD%' OR action LIKE '%ACCOUNT_SETUP%') AND (description LIKE '%$argon2%' OR description LIKE '%token=%' OR description LIKE '%password_hash%' OR description LIKE '%token_hash%' OR description LIKE '%/reset-password?r=%');
SELECT 'database_security_triggers' AS check_name, COUNT(*) AS violations FROM information_schema.triggers WHERE trigger_schema=DATABASE() AND event_object_table IN ('users','roles','user_roles','permissions','role_permissions','user_national_scopes','user_district_scopes','user_school_scopes','user_service_location_scopes','password_reset_requests','user_administration_lock');
SELECT 'multiple_active_reset_credentials' AS check_name, COUNT(*) AS violations FROM (SELECT user_id FROM password_reset_requests WHERE used_at IS NULL AND invalidated_at IS NULL AND expires_at>NOW() GROUP BY user_id HAVING COUNT(*)>1) d;
SELECT 'duplicate_active_scopes' AS check_name, COUNT(*) AS violations FROM (SELECT user_id,scope_type,COALESCE(entity_id,0) FROM admin_user_scopes GROUP BY user_id,scope_type,COALESCE(entity_id,0) HAVING COUNT(*)>1) d;
SELECT 'credential_expiry_policy' AS check_name, COUNT(*) AS violations FROM password_reset_requests WHERE TIMESTAMPDIFF(SECOND,created_at,expires_at) NOT BETWEEN 899 AND 900;
